import{_ as o,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-FEB-15 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-FEB-15 :: Ceph Performance Weekly","date":"2018-02-21T00:00:00.000Z","updated":"2018-02-21T00:00:00.000Z","tags":["Ceph性能优化","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏纠正码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-FEB-15_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-FEB-15_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),p={name:"posts/2018/2018-FEB-15_-_-_Ceph_Performance_Weekly.md"};function s(i,e,n,a,_,g){return t(),l("div",null,[...e[0]||(e[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年X月X日</p><p><strong>参会人员</strong>： [此处列出参会人员姓名]</p><p><strong>会议主题</strong>： Ceph存储性能优化与调试</p><p><strong>会议内容</strong>：</p><p><strong>一、性能优化</strong></p><ul><li>Retta Slav 在读性能测试中发现了两个主要问题： <ul><li>通过MD config T访问配置选项速度过慢，已提交PR进行优化。</li><li>在非调试模式下填充流（oh streams）导致性能下降，已提交PR进行修复。</li></ul></li><li>作者在PTO期间发现memstore性能较慢，通过使用基于向量的对象存储和性能修复，显著提高了性能。</li><li>作者发现pg log对CPU消耗影响较大，尤其是在使用in-memory vector-based存储时，CPU消耗从5个核心降至约3个核心。</li><li>作者认为需要进一步优化pg log，并考虑使用PG ring buffers来提高性能。</li></ul><p><strong>二、调试设施</strong></p><ul><li>作者发现mutex和perf counters对性能影响较大，特别是在finisher thread和OSD操作中。</li><li>作者认为需要优化mutex的使用，并考虑使用更高效的机制。</li><li>作者发现lock depth参数对性能影响较大，建议默认设置为none。</li></ul><p><strong>三、其他</strong></p><ul><li>作者提出了一个新的object store playground项目，名为pet store，用于测试不同的性能优化方案。</li><li>作者认为需要进一步优化object info T结构和PG info结构。</li><li>Adam正在尝试使用off FFI编译Ceph，以验证性能表现。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>作者将继续优化pg log和性能相关代码。</li><li>作者将进一步优化mutex的使用，并考虑使用更高效的机制。</li><li>Adam将继续测试使用off FFI编译Ceph的性能表现。</li><li>全体成员将继续关注Ceph的性能优化和调试工作。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文关键词，如：performance pull requests, MD config T, memstore, pg log, mutex, perf counters, lock depth, off FFI等。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph存储性能优化和调试的相关问题，并提出了后续行动计划。会议强调了优化pg log和mutex使用的重要性，并建议继续探索新的性能优化方案。</p>",17)])])}const f=o(p,[["render",s]]);export{c as __pageData,f as default};
